const FORMULAS = [
 {id:"ar", cat:"Epi", name:"Attack Rate (Incidence Proportion)", f:"new cases ÷ population at risk × 100", ins:[["New cases",30],["Population at risk",120]], calc:v=>v[0]/v[1]*100, unit:"%", tip:"Used in outbreaks. It's really a proportion, not a rate."},
 {id:"ir", cat:"Epi", name:"Incidence Rate", f:"new cases ÷ person-time at risk × 1,000", ins:[["New cases",12],["Person-years",4000]], calc:v=>v[0]/v[1]*1000, unit:"per 1,000 person-yrs", tip:"Person-time handles people followed for different lengths of time."},
 {id:"prev", cat:"Epi", name:"Prevalence", f:"existing cases ÷ total population × 1,000", ins:[["Existing cases",450],["Total population",5000]], calc:v=>v[0]/v[1]*1000, unit:"per 1,000", tip:"Snapshot of burden. Prevalence ≈ Incidence × Duration."},
 {id:"cfr", cat:"Epi", name:"Case Fatality Rate", f:"deaths from disease ÷ cases × 100", ins:[["Deaths",18],["Cases",40]], calc:v=>v[0]/v[1]*100, unit:"%", tip:"Measures severity — how deadly a disease is among people who have it."},
 {id:"sar", cat:"Epi", name:"Secondary Attack Rate", f:"cases among contacts ÷ susceptible contacts × 100", ins:[["Cases among contacts",6],["Susceptible contacts",24]], calc:v=>v[0]/v[1]*100, unit:"%", tip:"Measures how contagious something is in households or close contacts. Don't count the primary case."},
 {id:"cdr", cat:"Vital stats", name:"Crude Death Rate", f:"deaths ÷ mid-year population × 100,000", ins:[["Deaths",14000],["Mid-year population",1550000]], calc:v=>v[0]/v[1]*100000, unit:"per 100,000", tip:"'Crude' = not adjusted for age. Use age-adjusted rates to compare places."},
 {id:"imr", cat:"Vital stats", name:"Infant Mortality Rate", f:"infant deaths (<1 yr) ÷ live births × 1,000", ins:[["Infant deaths",150],["Live births",18000]], calc:v=>v[0]/v[1]*1000, unit:"per 1,000 live births", tip:"A key indicator of a community's overall health."},
 {id:"mmr", cat:"Vital stats", name:"Maternal Mortality Ratio", f:"maternal deaths ÷ live births × 100,000", ins:[["Maternal deaths",6],["Live births",18000]], calc:v=>v[0]/v[1]*100000, unit:"per 100,000 live births", tip:"It's a RATIO because the denominator (births) isn't the population at risk (pregnancies)."},
 {id:"ptb", cat:"Vital stats", name:"Preterm Birth Rate", f:"births < 37 wks ÷ live births × 100", ins:[["Preterm births",1900],["Live births",18000]], calc:v=>v[0]/v[1]*100, unit:"%", tip:"U.S. rate is about 10%."},
 {id:"rr", cat:"2×2 Table", name:"Risk Ratio (Relative Risk)", f:"[a ÷ (a+b)] ÷ [c ÷ (c+d)]", ins:[["a: exposed & sick",40],["b: exposed & well",60],["c: unexposed & sick",10],["d: unexposed & well",90]], calc:v=>(v[0]/(v[0]+v[1]))/(v[2]/(v[2]+v[3])), unit:"", tip:"Cohort studies. RR = 1 no association; >1 higher risk; <1 protective."},
 {id:"or", cat:"2×2 Table", name:"Odds Ratio", f:"(a × d) ÷ (b × c)", ins:[["a: cases exposed",30],["b: controls exposed",15],["c: cases unexposed",20],["d: controls unexposed",35]], calc:v=>(v[0]*v[3])/(v[1]*v[2]), unit:"", tip:"Case-control studies. Cross-multiply: ad over bc."},
 {id:"rd", cat:"2×2 Table", name:"Attributable Risk (Risk Difference)", f:"risk in exposed − risk in unexposed", ins:[["Risk exposed (%)",40],["Risk unexposed (%)",10]], calc:v=>v[0]-v[1], unit:"percentage points", tip:"How much disease is due to the exposure among exposed people."},
 {id:"arp", cat:"2×2 Table", name:"Attributable Risk %", f:"(Re − Ru) ÷ Re × 100", ins:[["Risk exposed (%)",40],["Risk unexposed (%)",10]], calc:v=>(v[0]-v[1])/v[0]*100, unit:"%", tip:"Share of exposed people's disease that's due to the exposure."},
 {id:"par", cat:"2×2 Table", name:"Population Attributable Risk %", f:"(R total − R unexposed) ÷ R total × 100", ins:[["Risk in total pop (%)",18],["Risk unexposed (%)",10]], calc:v=>(v[0]-v[1])/v[0]*100, unit:"%", tip:"How much disease in the WHOLE community you'd prevent by removing the exposure. Great for program planning pitches."},
 {id:"nnt", cat:"2×2 Table", name:"Number Needed to Treat", f:"1 ÷ absolute risk reduction (as a decimal)", ins:[["Risk control (%)",20],["Risk treated (%)",15]], calc:v=>1/((v[0]-v[1])/100), unit:"people", tip:"Always round UP in real life."},
 {id:"sens", cat:"Screening", name:"Sensitivity", f:"TP ÷ (TP + FN) × 100", ins:[["True positives",90],["False negatives",10]], calc:v=>v[0]/(v[0]+v[1])*100, unit:"%", tip:"SNOUT: a highly SeNsitive test, when Negative, rules OUT."},
 {id:"spec", cat:"Screening", name:"Specificity", f:"TN ÷ (TN + FP) × 100", ins:[["True negatives",850],["False positives",50]], calc:v=>v[0]/(v[0]+v[1])*100, unit:"%", tip:"SPIN: a highly SPecific test, when Positive, rules IN."},
 {id:"ppv", cat:"Screening", name:"Positive Predictive Value", f:"TP ÷ (TP + FP) × 100", ins:[["True positives",90],["False positives",50]], calc:v=>v[0]/(v[0]+v[1])*100, unit:"%", tip:"PPV goes UP when prevalence goes up."},
 {id:"npv", cat:"Screening", name:"Negative Predictive Value", f:"TN ÷ (TN + FN) × 100", ins:[["True negatives",850],["False negatives",10]], calc:v=>v[0]/(v[0]+v[1])*100, unit:"%", tip:"NPV goes DOWN when prevalence goes up."},
 {id:"hit", cat:"Vaccines", name:"Herd Immunity Threshold", f:"1 − (1 ÷ R0)", ins:[["R0",15]], calc:v=>(1-1/v[0])*100, unit:"% immune needed", tip:"Measles R0 12–18 → ~92–95% need immunity. That's why small drops in coverage matter."},
 {id:"vc", cat:"Vaccines", name:"Critical Vaccine Coverage", f:"(1 − 1/R0) ÷ vaccine effectiveness", ins:[["R0",15],["Vaccine effectiveness (%)",97]], calc:v=>(1-1/v[0])/(v[1]/100)*100, unit:"% must be vaccinated", tip:"Imperfect vaccines need higher coverage."},
 {id:"ve", cat:"Vaccines", name:"Vaccine Efficacy", f:"(ARU − ARV) ÷ ARU × 100  =  (1 − RR) × 100", ins:[["Attack rate unvaccinated (%)",20],["Attack rate vaccinated (%)",2]], calc:v=>(v[0]-v[1])/v[0]*100, unit:"%", tip:"Efficacy = trials. Effectiveness = real world."},
 {id:"smr", cat:"Biostats", name:"Standardized Mortality Ratio", f:"observed deaths ÷ expected deaths", ins:[["Observed deaths",130],["Expected deaths",100]], calc:v=>v[0]/v[1], unit:"", tip:"SMR > 1 = more deaths than expected. Used in occupational studies."},
 {id:"z", cat:"Biostats", name:"Z-score", f:"(x − mean) ÷ standard deviation", ins:[["Value (x)",130],["Mean",100],["SD",15]], calc:v=>(v[0]-v[1])/v[2], unit:"SDs from mean", tip:"±1.96 = the middle 95% of a normal curve."},
 {id:"ci", cat:"Biostats", name:"95% CI for a Proportion (half-width)", f:"1.96 × √[p(1−p) ÷ n]", ins:[["p (%)",30],["n (sample size)",400]], calc:v=>1.96*Math.sqrt((v[0]/100)*(1-v[0]/100)/v[1])*100, unit:"± percentage points", tip:"Bigger n = narrower interval = more precise."},
 {id:"pid", cat:"Epi", name:"Prevalence ≈ Incidence × Duration", f:"incidence rate × average duration", ins:[["Incidence (per 1,000/yr)",5],["Avg duration (yrs)",8]], calc:v=>v[0]*v[1], unit:"per 1,000", tip:"Better treatment that keeps people alive longer INCREASES prevalence."}
];

